[{"order":1,"type":"heading","text":"Routing and Route Parameters in Express.js"},{"order":2,"type":"paragraph","text":"Routing is a fundamental aspect of web frameworks like Express.js. It determines how an application responds to client requests for specific endpoints, which are combinations of a URI (or path) and a specific HTTP method (such as GET, POST, PUT, or DELETE)."},{"order":3,"type":"subheading","text":"Basic Routing Setup"},{"order":4,"type":"paragraph","text":"To define basic routes in Express, you call methods of the Express application object that correspond to HTTP methods. Here is how you can set up a basic server with simple GET and POST routes:"},{"order":5,"type":"code","text":"const express = require('express');
const app = express();
const PORT = 3000;

app.get('/', (req, res) => {
  res.send('Hello World!');
});

app.post('/submit', (req, res) => {
  res.send('Data received successfully');
});

app.listen(PORT, () => {
  console.log('Server is running on port ' + PORT);
});"},{"order":6,"type":"subheading","text":"Understanding Route Parameters"},{"order":7,"type":"paragraph","text":"Route parameters are named URL segments that are used to capture the values specified at their position in the URL. The captured values are populated in the req.params object, with the name of the route parameter specified in the path as their respective keys."},{"order":8,"type":"code","text":"// Route with a single parameter
app.get('/users/:userId', (req, res) => {
  const userId = req.params.userId;
  res.send('Retrieved user with ID: ' + userId);
});

// Route with multiple parameters
app.get('/flights/:from/:to', (req, res) => {
  const origin = req.params.from;
  const destination = req.params.to;
  res.send('Flight from ' + origin + ' to ' + destination);
});"},{"order":9,"type":"subheading","text":"Key Rules for Route Parameters"},{"order":10,"type":"bullet_point","text":"Route parameters must be prefixed with a colon (:)."},{"order":11,"type":"bullet_point","text":"Characters like hyphens (-) and periods (.) are interpreted literally and can be used alongside parameters for useful formatting."},{"order":12,"type":"bullet_point","text":"Access parameters seamlessly using the req.params object inside your route handler callback."}]
